export {
  NumberField,
  NumberFieldScrubArea,
  NumberFieldScrubAreaCursor,
  NumberFieldGroup,
  NumberFieldDecrement,
  NumberFieldInput,
  NumberFieldIncrement,
} from "./number-field";

import { tv, type VariantProps } from "tailwind-variants";

const numberField = tv({
  slots: {
    root: "flex flex-col items-start gap-1.5",
    scrubArea: [
      "w-full cursor-ew-resize transition-opacity duration-150 ease-default select-none",
      "data-disabled:pointer-events-none data-disabled:opacity-50",
      "[&>label]:cursor-ew-resize",
    ],
    scrubAreaCursor: "",
    group: [
      "group flex items-center overflow-clip rounded-md border border-input bg-background shadow-sm transition-[border-color,box-shadow,opacity] duration-150 ease-default",
      "focus-within:ring-2 focus-within:ring-ring",
      "data-disabled:opacity-50",
      "data-invalid:border-destructive",
      "focus-within:data-invalid:ring-destructive",
      "dark:bg-input/15",
    ],
    decrement: [
      "flex h-full items-center justify-center bg-muted text-foreground transition-colors duration-150 ease-default select-none",
      "hover:bg-accent hover:text-accent-foreground",
      "data-disabled:pointer-events-none",
    ],
    input: [
      "h-full items-center rounded-[inherit] text-center text-foreground tabular-nums outline-none",
      "group-has-data-[slot='number-field-decrement']:rounded-s-none",
      "group-has-data-[slot='number-field-increment']:rounded-e-none",
      "placeholder:text-muted-foreground",
      "any-pointer-coarse:text-base",
    ],
    increment: [
      "flex h-full items-center justify-center bg-muted text-foreground transition-colors duration-150 ease-default select-none",
      "hover:bg-accent hover:text-accent-foreground",
      "data-disabled:pointer-events-none",
    ],
  },
  variants: {
    size: {
      lg: {
        group: "h-10",
        decrement: "w-10 [&>svg:not([class*='size-'])]:size-4",
        input: "text-base",
        increment: "w-10 [&>svg:not([class*='size-'])]:size-4",
      },
      md: {
        group: "h-9",
        decrement: "w-9 [&>svg:not([class*='size-'])]:size-3.5",
        input: "text-sm",
        increment: "w-9 [&>svg:not([class*='size-'])]:size-3.5",
      },
      sm: {
        group: "h-8",
        decrement: "w-8 [&>svg:not([class*='size-'])]:size-3",
        input: "text-xs",
        increment: "w-8 [&>svg:not([class*='size-'])]:size-3",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

type NumberFieldVariantProps = VariantProps<typeof numberField>;

export { numberField };
export type { NumberFieldVariantProps };

"use client";

import { useDirection } from "@base-ui/react";
import { NumberField as BaseNumberField } from "@base-ui/react/number-field";
import { MinusIcon, MoveHorizontalIcon, PlusIcon } from "lucide-react";
import { createContext, useContext } from "react";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import {
  numberField,
  type NumberFieldVariantProps,
} from "./number-field.style";

type NumberFieldContext = NumberFieldVariantProps;

const NumberFieldContext = createContext<NumberFieldContext>({
  size: "md",
});

function useNumberField() {
  return useContext(NumberFieldContext);
}

function NumberField({
  size,
  className,
  children,
  ...props
}: BaseNumberField.Root.Props & NumberFieldVariantProps) {
  const direction = useDirection();

  return (
    <NumberFieldContext.Provider value={{ size }}>
      <BaseNumberField.Root
        data-slot="number-field"
        className={mergeSlotClassName(numberField().root, className)}
        {...props}
        dir={direction}
      >
        {children}
      </BaseNumberField.Root>
    </NumberFieldContext.Provider>
  );
}

function NumberFieldScrubArea({
  className,
  ...props
}: BaseNumberField.ScrubArea.Props) {
  return (
    <BaseNumberField.ScrubArea
      data-slot="number-field-scrub-area"
      className={mergeSlotClassName(numberField().scrubArea, className)}
      {...props}
    />
  );
}

function NumberFieldScrubAreaCursor({
  className,
  children,
  ...props
}: BaseNumberField.ScrubAreaCursor.Props) {
  return (
    <BaseNumberField.ScrubAreaCursor
      data-slot="number-field-scrub-area-cursor"
      className={mergeSlotClassName(numberField().scrubAreaCursor, className)}
      {...props}
    >
      {children ?? <MoveHorizontalIcon />}
    </BaseNumberField.ScrubAreaCursor>
  );
}

function NumberFieldGroup({
  className,
  ...props
}: BaseNumberField.Group.Props) {
  const { size } = useNumberField();

  return (
    <BaseNumberField.Group
      data-slot="number-field-group"
      className={mergeSlotClassName(numberField({ size }).group, className)}
      {...props}
    />
  );
}

function NumberFieldDecrement({
  className,
  children,
  ...props
}: BaseNumberField.Decrement.Props) {
  const { size } = useNumberField();

  return (
    <BaseNumberField.Decrement
      data-slot="number-field-decrement"
      className={mergeSlotClassName(numberField({ size }).decrement, className)}
      {...props}
    >
      {children ?? <MinusIcon />}
    </BaseNumberField.Decrement>
  );
}

function NumberFieldInput({
  className,
  ...props
}: BaseNumberField.Input.Props) {
  const { size } = useNumberField();

  return (
    <BaseNumberField.Input
      data-slot="number-field-input"
      className={mergeSlotClassName(numberField({ size }).input, className)}
      {...props}
    />
  );
}

function NumberFieldIncrement({
  className,
  children,
  ...props
}: BaseNumberField.Increment.Props) {
  const { size } = useNumberField();

  return (
    <BaseNumberField.Increment
      data-slot="number-field-increment"
      className={mergeSlotClassName(numberField({ size }).increment, className)}
      {...props}
    >
      {children ?? <PlusIcon />}
    </BaseNumberField.Increment>
  );
}

export {
  NumberField,
  NumberFieldScrubArea,
  NumberFieldScrubAreaCursor,
  NumberFieldGroup,
  NumberFieldDecrement,
  NumberFieldInput,
  NumberFieldIncrement,
};
